$env:SPRING_MAIN_ALLOW_BEAN_DEFINITION_OVERRIDING="true"; $env:SPRING_JPA_HIBERNATE_DDL_AUTO="update"; $env:SPRING_MAIL_HOST="localhost"; $env:SPRING_MAIL_PORT="1025"; $env:MANAGEMENT_HEALTH_MAIL_ENABLED="false"; $env:JWT_SECRET="hrms-platform-jwt-secret-key-change-this-in-production-256bit!!"; $env:SPRING_FLYWAY_OUT_OF_ORDER="true"
$root="C:\Users\ritwi\Desktop\HRMS-SaaS-Platform"; $java="C:\Program Files\Java\jdk-17\bin\java.exe"
function Start-Svc($name,$extra=""){ $jar=(Get-ChildItem "$root\$name\target\*.jar"|Where-Object{$_.Name -notmatch "sources|javadoc|original"}|Select-Object -First 1).FullName; $log="$root\logs\$name.log"; Start-Process -FilePath $java -ArgumentList "-Xmx320m -Xms64m -XX:TieredStopAtLevel=1 -Xss512k $extra -jar `"$jar`"" -RedirectStandardOutput $log -RedirectStandardError "$log.err" -WindowStyle Minimized -WorkingDirectory "$root\$name" | Out-Null }
